package main

import "fmt"

func main() {
	// Continue (Cetak hanya angka ganjil)
	fmt.Println("--- Continue Example ---")
	for i := 1; i <= 10; i++ {
		if i%2 == 0 {
			continue // Lewati angka genap
		}
		fmt.Println("Angka Ganjil:", i)
	}

	// Break
	fmt.Println("--- Break Example ---")
	for i := 1; i <= 10; i++ {
		if i == 5 {
			break // Berhenti total jika i == 5
		}
		fmt.Println("Iterasi ke-", i)
	}
}

