import "fmt"

func factorialRecursive(value int) int {
	if value == 1 {
		return 1
	}
	return value * factorialRecursive(value-1)
}

func main() {
	result := factorialRecursive(5) // 5 * 4 * 3 * 2 * 1 = 120
	fmt.Println("Faktorial 5! =", result)
}

