package main

import (
	"errors"
	"fmt"
)

var (
	ErrNotFound     = errors.New("data tidak ditemukan")
	ErrValidationError = errors.New("validasi gagal")
)

func GetById(id string) error {
	if id == "" {
		return ErrValidationError
	}
	if id != "eko" {
		return fmt.Errorf("search id %s: %w", id, ErrNotFound) // Wrapping Error
	}
	return nil
}

func main() {
	err := GetById("budi")

	if err != nil {
		if errors.Is(err, ErrNotFound) {
			fmt.Println("Pencarian Gagal: Data Not Found!")
		} else {
			fmt.Println("Error Lain:", err)
		}
	}
}

