package main

import (
	"fmt"
	"sort"
)

type User struct {
	Name string
	Age  int
}

type UserSlice []User

func (s UserSlice) Len() int           { return len(s) }
func (s UserSlice) Less(i, j int) bool { return s[i].Age < s[j].Age } // Sort by Age
func (s UserSlice) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

func main() {
	users := UserSlice{
		{"Eko", 30},
		{"Budi", 25},
		{"Joko", 35},
	}

	sort.Sort(users)
	fmt.Println("Sorted Users by Age:", users)
}

