package main

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Simulasi errgroup sederhana
type Grup struct {
	wg      sync.WaitGroup
	mu      sync.Mutex
	err     error
	batal   chan struct{}
	sekali  sync.Once
}

func (g *Grup) Go(fn func() error) {
	g.wg.Add(1)
	go func() {
		defer g.wg.Done()
		if err := fn(); err != nil {
			g.mu.Lock()
			if g.err == nil {
				g.err = err
				g.sekali.Do(func() { close(g.batal) })
			}
			g.mu.Unlock()
		}
	}()
}

func (g *Grup) Wait() error { g.wg.Wait(); return g.err }

func main() {
	g := &Grup{batal: make(chan struct{})}

	tugas := []string{"api-a", "api-b", "api-c"}
	for i, nama := range tugas {
		gagal := i == 1
		g.Go(func() error {
			time.Sleep(time.Duration(i+1) * 50 * time.Millisecond)
			if gagal {
				fmt.Println("  ✗", nama, "GAGAL")
				return errors.New(nama + ": koneksi ditolak")
			}
			fmt.Println("  ✓", nama, "sukses")
			return nil
		})
	}

	if err := g.Wait(); err != nil {
		fmt.Println("\nError pertama:", err)
		return
	}
	fmt.Println("\nSemua berhasil")
}

