import (
	"fmt"
	"strconv"
	"strings"
)

// Fungsi yang akan di-fuzz
func UraiWaktu(s string) (jam, menit int, err error) {
	bagian := strings.Split(s, ":")
	if len(bagian) != 2 {
		return 0, 0, fmt.Errorf("format tidak valid: %q", s)
	}
	jam, err = strconv.Atoi(bagian[0])
	if err != nil {
		return 0, 0, err
	}
	menit, err = strconv.Atoi(bagian[1])
	if err != nil {
		return 0, 0, err
	}
	if jam < 0 || jam > 23 || menit < 0 || menit > 59 {
		return 0, 0, fmt.Errorf("di luar rentang: %q", s)
	}
	return jam, menit, nil
}

func main() {
	// Masukan yang biasanya ditemukan fuzzer
	masukan := []string{"12:30", "00:00", "23:59", "24:00", "-1:30", "12:60", "12", "::", "", "12:3a"}

	for _, s := range masukan {
		j, m, err := UraiWaktu(s)
		if err != nil {
			fmt.Printf("%-8q -> ditolak: %v\n", s, err)
			continue
		}
		fmt.Printf("%-8q -> %02d:%02d ✓\n", s, j, m)
	}
}

