	FeatureFlag  bool
}

func (c *DynamicConfig) UpdateFlag(val bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.FeatureFlag = val
	fmt.Println("[EVENT] Config updated! FeatureFlag is now:", val)
}

func (c *DynamicConfig) IsEnabled() bool {
