package main

import (
	"fmt"
	"regexp"
)

type Employee struct {
	Name   string
	Email  string
	Age    int
	Salary float64
}

func ValidateEmployee(e Employee) map[string]string {
	errs := make(map[string]string)
	if len(e.Name) < 3 || len(e.Name) > 20 {
		errs["Name"] = "Name harus antara 3 hingga 20 karakter"
	}
	emailRegex := regexp.MustCompile(`^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,4}$`)
	if !emailRegex.MatchString(strings.ToLower(e.Email)) {
		errs["Email"] = "Format email tidak valid"
	}
	if e.Age < 18 || e.Age > 65 {
		errs["Age"] = "Age harus antara 18 dan 65 tahun"
	}
	if e.Salary <= 0 {
		errs["Salary"] = "Salary harus lebih besar dari 0"
	}
	return errs
}

func main() {
	emp := Employee{
		Name:   "B",
		Email:  "budi.com",
		Age:    15,
		Salary: 0,
	}

	errs := ValidateEmployee(emp)
	fmt.Println("=== HASIL VALIDASI EMPLOYEE ===")
	for field, msg := range errs {
		fmt.Printf("- Field '%s': %s\n", field, msg)
	}
}

