)

type Item struct {
	Name  string
	Price float64
	Qty   int
}

type Order struct {
	OrderID     string
	Customer    string
	Items       []Item
}

func ValidateOrder(o Order) []string {
	var errs []string
	if o.OrderID == "" {
		errs = append(errs, "OrderID tidak boleh kosong")
	}
	if o.Customer == "" {
		errs = append(errs, "Customer tidak boleh kosong")
	}
	if len(o.Items) == 0 {
		errs = append(errs, "Order harus memiliki setidaknya 1 item")
	}
	for i, item := range o.Items {
		if item.Name == "" {
			errs = append(errs, fmt.Sprintf("Item [%d]: Name tidak boleh kosong", i))
		}
		if item.Price <= 0 {
			errs = append(errs, fmt.Sprintf("Item [%d]: Price harus > 0", i))
		}
		if item.Qty <= 0 {
			errs = append(errs, fmt.Sprintf("Item [%d]: Qty harus > 0", i))
		}
	}
	return errs
}

func main() {
	order := Order{
		OrderID:  "ORD-991",
		Customer: "Andi",
		Items: []Item{
			{Name: "Laptop", Price: 12000000, Qty: 1},
			{Name: "", Price: 0, Qty: 0}, // Invalid item
		},
	}

	errs := ValidateOrder(order)
	fmt.Println("=== VALIDASI NESTED ORDER ===")
	if len(errs) > 0 {
		for _, e := range errs {
			fmt.Println("ERROR:", e)
		}
	} else {
		fmt.Println("Order Valid!")
	}
}

