package main

import (
	"fmt"
)

type Account struct {
	Balance float64
}

func TransferMoney(from, to *Account, amount float64) error {
	if from.Balance < amount {
		return fmt.Errorf("ROLLBACK: Saldo pengirim tidak mencukupi")
	}
	from.Balance -= amount
	to.Balance += amount
	return nil // COMMIT
}

func main() {
	acc1 := &Account{Balance: 500000}
	acc2 := &Account{Balance: 100000}

	fmt.Println("=== SIMULASI TRANSACTION TRANSFER ===")
	err := TransferMoney(acc1, acc2, 200000)
	if err == nil {
		fmt.Println("TRANSAKSI COMMIT BERHASIL!")
		fmt.Printf("Saldo Acc1: %.0f | Saldo Acc2: %.0f\n", acc1.Balance, acc2.Balance)
	}
}

