import (
	"errors"
	"fmt"
)

// Simulasi error PostgreSQL
type PgError struct {
	Code    string
	Message string
	Detail  string
}

func (e *PgError) Error() string { return fmt.Sprintf("pg %s: %s", e.Code, e.Message) }

var (
	ErrEmailSudahDipakai  = errors.New("email sudah terdaftar")
	ErrReferensiTidakSah  = errors.New("referensi tidak sah")
	ErrCobaLagi           = errors.New("bentrok sementara, coba lagi")
)

func terjemahkan(err error) error {
	var pgErr *PgError
	if !errors.As(err, &pgErr) {
		return err
	}
	switch pgErr.Code {
	case "23505":
		return ErrEmailSudahDipakai
	case "23503":
		return ErrReferensiTidakSah
	case "40001", "40P01":
		return ErrCobaLagi
	}
	return err
}

func main() {
	kasus := []error{
		&PgError{Code: "23505", Message: "duplicate key value violates unique constraint", Detail: "Key (email)=(budi@contoh.com) already exists."},
		&PgError{Code: "23503", Message: "insert or update violates foreign key constraint"},
		&PgError{Code: "40P01", Message: "deadlock detected"},
		&PgError{Code: "42P01", Message: "relation \"pesananx\" does not exist"},
	}

	for _, err := range kasus {
		hasil := terjemahkan(err)
		dapatDiulang := errors.Is(hasil, ErrCobaLagi)
		fmt.Printf("%-8s -> %-32v (boleh diulang: %v)\n",
			err.(*PgError).Code, hasil, dapatDiulang)
	}
}

package main

import "fmt"

// Simulasi struct & fungsi hasil bangkitan sqlc
type StatusPesanan string

const (
	StatusMenunggu StatusPesanan = "MENUNGGU"
	StatusDibayar  StatusPesanan = "DIBAYAR"
)

type Pesanan struct {
	ID         string        `json:"id"`
	PenggunaID int64         `json:"pengguna_id"`
	Total      int64         `json:"total"`
	Status     StatusPesanan `json:"status"`
}

type BuatPesananParams struct {
	PenggunaID int64
	Total      int64
	Status     StatusPesanan
}

type Queries struct{ data map[string]Pesanan; urut []string }

func (q *Queries) BuatPesanan(arg BuatPesananParams) (Pesanan, error) {
	id := fmt.Sprintf("p-%04d", len(q.urut)+1001)
	p := Pesanan{ID: id, PenggunaID: arg.PenggunaID, Total: arg.Total, Status: arg.Status}
	q.data[id] = p
	q.urut = append(q.urut, id)
	return p, nil
}

func (q *Queries) DaftarPesananPengguna(penggunaID int64) ([]Pesanan, error) {
	var hasil []Pesanan
	for _, id := range q.urut {
		if p := q.data[id]; p.PenggunaID == penggunaID {
			hasil = append(hasil, p)
		}
	}
	return hasil, nil
}

func main() {
	q := &Queries{data: map[string]Pesanan{}}

	q.BuatPesanan(BuatPesananParams{PenggunaID: 55, Total: 250000, Status: StatusMenunggu})
	q.BuatPesanan(BuatPesananParams{PenggunaID: 55, Total: 89000, Status: StatusDibayar})
	q.BuatPesanan(BuatPesananParams{PenggunaID: 71, Total: 45000, Status: StatusMenunggu})

	daftar, _ := q.DaftarPesananPengguna(55)
	fmt.Println("Pesanan milik pengguna 55:")
	for _, p := range daftar {
		fmt.Printf("  %s  Rp%-8d  %s\n", p.ID, p.Total, p.Status)
	}

	fmt.Println("\nSemua field aman tipe -- salah ketik ditangkap compiler.")
}

