package main

import (
	"fmt"
)

func main() {
	// Simulasi FIFO Queue dengan Slice
	var queue []string

	// LPUSH (Push to head)
	queue = append([]string{"job_email_1"}, queue...)
	queue = append([]string{"job_email_2"}, queue...)

	fmt.Println("=== REDIS LIST FIFO QUEUE SIMULATION ===")
	fmt.Println("Current Queue Contents:", queue)

	// RPOP (Pop from tail)
	lastJob := queue[len(queue)-1]
	queue = queue[:len(queue)-1]
	fmt.Println("Processed Job (RPop):", lastJob)
	fmt.Println("Remaining Queue:", queue)
}

