package main

import (
	"fmt"
)

type ProductCache struct {
	redisData map[string]string
	dbData    map[string]string
}

func (pc *ProductCache) GetProduct(id string) (string, string) {
	// 1. Cek Redis
	if val, ok := pc.redisData[id]; ok {
		return val, "CACHE_HIT (From Redis RAM)"
	}

	// 2. Query SQL DB
	val := pc.dbData[id]

	// 3. Populate Redis
	pc.redisData[id] = val
	return val, "CACHE_MISS (Query SQL & Saved to Redis)"
}

func main() {
	cache := ProductCache{
		redisData: make(map[string]string),
		dbData:    map[string]string{"prod_1": "Laptop Gaming ASUS"},
	}

	fmt.Println("=== DEMO CACHE-ASIDE PATTERN ===")
	// Request 1: Cache Miss
	val1, source1 := cache.GetProduct("prod_1")
	fmt.Printf("Req #1 => Value: %s | Source: %s\n", val1, source1)

	// Request 2: Cache Hit
	val2, source2 := cache.GetProduct("prod_1")
	fmt.Printf("Req #2 => Value: %s | Source: %s\n", val2, source2)
}

