	StatusTidakDiketahui StatusPesanan = 0
	StatusMenunggu       StatusPesanan = 1
	StatusDibayar        StatusPesanan = 2
)

func (s StatusPesanan) String() string {
	switch s {
	case StatusMenunggu:
		return "MENUNGGU"
	case StatusDibayar:
		return "DIBAYAR"
	default:
		return "TIDAK_DIKETAHUI"
	}
}

type ItemPesanan struct {
	ProdukId string
	Jumlah   int32
	Harga    int64
}

type Pesanan struct {
	Id         string
	PenggunaId int64
	Total      int64
	Status     StatusPesanan
	Item       []*ItemPesanan
}

// Getter nil-safe, persis seperti yang dibangkitkan protoc
func (p *Pesanan) GetTotal() int64 {
	if p == nil {
		return 0
	}
	return p.Total
}

func main() {
	p := &Pesanan{
		Id: "p-1001", PenggunaId: 55, Status: StatusMenunggu,
		Item: []*ItemPesanan{
			{ProdukId: "kopi-gayo", Jumlah: 2, Harga: 85000},
			{ProdukId: "gula-aren", Jumlah: 1, Harga: 25000},
		},
	}
	for _, it := range p.Item {
