}

package main

import (
	"fmt"
	"time"
)

// Simulasi rantai interceptor gRPC
type Handler func(req string) (string, error)
type Interceptor func(req string, info string, next Handler) (string, error)

func Rantai(interceptors ...Interceptor) func(string, string, Handler) (string, error) {
	return func(req, info string, akhir Handler) (string, error) {
		var bungkus func(i int) Handler
		bungkus = func(i int) Handler {
			if i == len(interceptors) {
				return akhir
			}
			return func(r string) (string, error) {
				return interceptors[i](r, info, bungkus(i+1))
			}
		}
		return bungkus(0)(req)
	}
}

func main() {
	log := func(req, info string, next Handler) (string, error) {
		mulai := time.Now()
		fmt.Println("[log]  masuk  ->", info)
		resp, err := next(req)
		fmt.Printf("[log]  keluar <- %s (%v)\n", info, time.Since(mulai).Round(time.Microsecond))
		return resp, err
	}

	auth := func(req, info string, next Handler) (string, error) {
		fmt.Println("[auth] memverifikasi token")
		if req == "tanpa-token" {
			return "", fmt.Errorf("Unauthenticated: token tidak ada")
		}
		return next(req)
	}

	inti := func(req string) (string, error) {
		return "pesanan untuk " + req, nil
	}

	jalan := Rantai(log, auth)

	fmt.Println("=== Permintaan sah ===")
	resp, _ := jalan("user-55", "/pesanan.v1/AmbilPesanan", inti)
	fmt.Println("hasil:", resp)

	fmt.Println("\n=== Permintaan tanpa token ===")
	_, err := jalan("tanpa-token", "/pesanan.v1/AmbilPesanan", inti)
	fmt.Println("error:", err)
}

package main

import (
	"context"
	"fmt"
	"time"
)

// Simulasi span & konteks trace
type kunciSpan struct{}

type Span struct {
	Nama    string
	TraceID string
	SpanID  string
	Induk   string
	Mulai   time.Time
	Atribut map[string]any
}

var terkumpul []*Span
var penghitung int

func Mulai(ctx context.Context, nama string) (context.Context, *Span) {
	penghitung++
	s := &Span{Nama: nama, TraceID: "4bf92f35", SpanID: fmt.Sprintf("span-%02d", penghitung), Mulai: time.Now(), Atribut: map[string]any{}}
	if induk, ok := ctx.Value(kunciSpan{}).(*Span); ok {
		s.Induk = induk.SpanID
	}
	terkumpul = append(terkumpul, s)
	return context.WithValue(ctx, kunciSpan{}, s), s
}

func main() {
	ctx := context.Background()

	ctx, akar := Mulai(ctx, "POST /pesanan")
	akar.Atribut["pengguna.id"] = 55

	func(ctx context.Context) {
		ctx, s := Mulai(ctx, "periksaStok")
		s.Atribut["item.jumlah"] = 2
		func(ctx context.Context) {
			_, db := Mulai(ctx, "SELECT stok")
			db.Atribut["db.system"] = "postgresql"
		}(ctx)
	}(ctx)

	func(ctx context.Context) {
		_, s := Mulai(ctx, "simpanPesanan")
		s.Atribut["db.operation"] = "INSERT"
	}(ctx)

	fmt.Println("Trace ID:", akar.TraceID)
	for _, s := range terkumpul {
		indent := ""
		if s.Induk != "" {
			indent = "  └─ "
		}
		fmt.Printf("%s%-16s [%s] induk=%-8s %v\n", indent, s.Nama, s.SpanID, s.Induk, s.Atribut)
	}
}

