import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"
)

type Pengguna struct {
	ID       int64
	Email    string
	Password string
}

func samarkanEmail(e string) string {
	bagian := strings.SplitN(e, "@", 2)
	if len(bagian) != 2 || len(bagian[0]) < 2 {
		return "***"
	}
	return bagian[0][:2] + "***@" + bagian[1]
}

// Meniru slog.LogValuer
func (p Pengguna) NilaiLog() map[string]any {
	return map[string]any{
		"id":    p.ID,
		"email": samarkanEmail(p.Email),
		// Password sengaja tidak disertakan
	}
}

func catat(level, pesan string, kv ...any) {
	rec := map[string]any{
		"waktu": time.Now().UTC().Format(time.RFC3339),
		"level": level,
		"msg":   pesan,
	}
	sensitif := map[string]bool{"password": true, "token": true, "cvv": true}
	for i := 0; i+1 < len(kv); i += 2 {
		k := fmt.Sprint(kv[i])
		v := kv[i+1]
		if sensitif[strings.ToLower(k)] {
			v = "[DISUNTING]"
		}
		if p, ok := v.(Pengguna); ok {
			v = p.NilaiLog()
		}
		rec[k] = v
	}
	enc := json.NewEncoder(os.Stdout)
	enc.Encode(rec)
}

func main() {
	p := Pengguna{ID: 55, Email: "budi.santoso@contoh.com", Password: "rahasia123"}

	catat("INFO", "pengguna masuk", "pengguna", p, "request_id", "req-abc123")
	catat("INFO", "pesanan dibuat", "pesanan_id", "p-1001", "total", 250000)
	catat("ERROR", "pembayaran gagal", "pesanan_id", "p-1001", "token", "tok_live_xyz", "error", "kartu ditolak")
}

