}

package main

import (
	"fmt"
	"net/http"
	"log"
)

// Go app yang di-proxy oleh Nginx
func main() {
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		// Dapatkan IP asli client dari header Nginx
		realIP := r.Header.Get("X-Real-IP")
		if realIP == "" {
			realIP = r.RemoteAddr
		}

		proto := r.Header.Get("X-Forwarded-Proto")
		if proto == "" {
			proto = "http"
		}

		fmt.Fprintf(w, "Request diterima!\nClient IP: %s\nProtocol: %s\nHost: %s\nPath: %s",
			realIP, proto, r.Host, r.URL.Path)
	})

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintln(w, `{"status":"ok"}`)
	})

	// Go app hanya listen di localhost (Nginx yang expose ke internet)
	log.Println("Go backend berjalan di :8080 (behind Nginx)")
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", nil))
}

