// Fungsi yang akan ditest dalam CI/CD pipeline
func add(a, b int) int {
	return a + b
}

func multiply(a, b int) int {
	return a * b
}

// Test functions (file ini biasanya di main_test.go)
func TestAdd(t *testing.T) {
	result := add(3, 4)
	if result != 7 {
		t.Errorf("add(3, 4) = %d, want 7", result)
	}
}

func TestMultiply(t *testing.T) {
	cases := []struct {
		a, b, expected int
	}{
		{2, 3, 6},
		{0, 5, 0},
		{-1, 4, -4},
	}
	for _, tc := range cases {
		result := multiply(tc.a, tc.b)
