package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

// ── Data Model ──
type Product struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Price     float64   `json:"price"`
	Stock     int       `json:"stock"`
	CreatedAt time.Time `json:"created_at"`
}

// ── In-Memory Store ──
var store = struct {
	sync.RWMutex
	products map[int]Product
	nextID   int
}{products: make(map[int]Product), nextID: 1}

// ── Helper Functions ──
func jsonResponse(w http.ResponseWriter, code int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(data)
}

func getIDFromPath(path string) (int, error) {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) < 2 {
		return 0, fmt.Errorf("no id")
	}
	return strconv.Atoi(parts[len(parts)-1])
}

// ── Handlers ──
func listProducts(w http.ResponseWriter, r *http.Request) {
	store.RLock()
	defer store.RUnlock()
	products := make([]Product, 0, len(store.products))
	for _, p := range store.products {
		products = append(products, p)
	}
	jsonResponse(w, 200, products)
}

func createProduct(w http.ResponseWriter, r *http.Request) {
	var p Product
	if err := json.NewDecoder(r.Body).Decode(&p); err != nil {
		jsonResponse(w, 400, map[string]string{"error": "invalid JSON"})
		return
	}
	store.Lock()
	defer store.Unlock()
	p.ID = store.nextID
	p.CreatedAt = time.Now()
	store.products[p.ID] = p
	store.nextID++
	jsonResponse(w, 201, p)
}

func main() {
	// Seed data awal
	store.products[1] = Product{ID: 1, Name: "Laptop Go", Price: 15000000, Stock: 10, CreatedAt: time.Now()}
	store.products[2] = Product{ID: 2, Name: "Go Book", Price: 150000, Stock: 50, CreatedAt: time.Now()}
	store.nextID = 3

	mux := http.NewServeMux()
	mux.HandleFunc("/products", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case "GET":
			listProducts(w, r)
		case "POST":
			createProduct(w, r)
		default:
			jsonResponse(w, 405, map[string]string{"error": "method not allowed"})
		}
	})

	fmt.Println("REST API Server berjalan di :8080")
	fmt.Println("GET  /products         → list semua produk")
	fmt.Println("POST /products         → buat produk baru")
	http.ListenAndServe(":8080", mux)
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"
	"time"
)

const (
	Version   = "1.0.0"
	DataFile  = "notes.json"
)

type Note struct {
	ID        int       `json:"id"`
	Content   string    `json:"content"`
	CreatedAt time.Time `json:"created_at"`
}

func loadNotes() []Note {
	data, err := os.ReadFile(DataFile)
	if err != nil {
		return []Note{}
	}
	var notes []Note
	json.Unmarshal(data, &notes)
	return notes
}

func saveNotes(notes []Note) {
	data, _ := json.MarshalIndent(notes, "", "  ")
	os.WriteFile(DataFile, data, 0644)
}

func addNote(content string) {
	notes := loadNotes()
	nextID := 1
	if len(notes) > 0 {
		nextID = notes[len(notes)-1].ID + 1
	}
	notes = append(notes, Note{
		ID: nextID, Content: content, CreatedAt: time.Now(),
	})
	saveNotes(notes)
	fmt.Printf("✅ Catatan #%d ditambahkan!\n", nextID)
}

func listNotes() {
	notes := loadNotes()
	if len(notes) == 0 {
		fmt.Println("📭 Belum ada catatan.")
		return
	}
	fmt.Printf("📋 Total %d catatan:\n\n", len(notes))
	for _, n := range notes {
		fmt.Printf("[%d] %s\n    📅 %s\n\n",
			n.ID, n.Content, n.CreatedAt.Format("2006-01-02 15:04"))
	}
}

func deleteNote(id int) {
	notes := loadNotes()
	newNotes := make([]Note, 0)
	deleted := false
	for _, n := range notes {
		if n.ID != id {
			newNotes = append(newNotes, n)
		} else {
			deleted = true
		}
	}
	if deleted {
		saveNotes(newNotes)
		fmt.Printf("🗑️ Catatan #%d dihapus!\n", id)
	} else {
		fmt.Printf("❌ Catatan #%d tidak ditemukan.\n", id)
	}
}

func main() {
	versionFlag := flag.Bool("version", false, "Tampilkan versi")
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, `MyNote CLI v%s - Manajemen Catatan Go

Usage: mynote <command> [arguments]

Commands:
  add <catatan>   Tambah catatan baru
  list            Tampilkan semua catatan
  delete <id>     Hapus catatan berdasarkan ID

Flags:
`, Version)
		flag.PrintDefaults()
	}
	flag.Parse()

	if *versionFlag {
		fmt.Println("MyNote CLI v" + Version)
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		return
	}

	switch args[0] {
	case "add":
		if len(args) < 2 {
			fmt.Println("❌ Gunakan: mynote add <isi catatan>")
			return
		}
		addNote(args[1])
	case "list":
		listNotes()
	case "delete":
		if len(args) < 2 {
			fmt.Println("❌ Gunakan: mynote delete <id>")
			return
		}
		id, err := strconv.Atoi(args[1])
		if err != nil {
			fmt.Println("❌ ID harus berupa angka")
			return
		}
		deleteNote(id)
	default:
		fmt.Printf("❌ Perintah tidak dikenal: %s\n", args[0])
		flag.Usage()
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"time"
)

type Priority string

const (
	Low    Priority = "low"
	Medium Priority = "medium"
	High   Priority = "high"
)

type Task struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Priority  Priority  `json:"priority"`
	Done      bool      `json:"done"`
	CreatedAt time.Time `json:"created_at"`
}

type TaskManager struct {
	Tasks    []Task `json:"tasks"`
	NextID   int    `json:"next_id"`
	filePath string
}

func NewTaskManager(filePath string) *TaskManager {
	tm := &TaskManager{filePath: filePath, NextID: 1}
	tm.load()
	return tm
}

func (tm *TaskManager) load() {
	data, err := os.ReadFile(tm.filePath)
	if err != nil {
		return
	}
	json.Unmarshal(data, tm)
}

func (tm *TaskManager) save() error {
	data, err := json.MarshalIndent(tm, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(tm.filePath, data, 0644)
}

func (tm *TaskManager) Add(title string, priority Priority) Task {
	task := Task{
		ID: tm.NextID, Title: title,
		Priority: priority, CreatedAt: time.Now(),
	}
	tm.Tasks = append(tm.Tasks, task)
	tm.NextID++
	tm.save()
	return task
}

func (tm *TaskManager) Complete(id int) bool {
	for i, t := range tm.Tasks {
		if t.ID == id {
			tm.Tasks[i].Done = true
			tm.save()
			return true
		}
	}
	return false
}

func (tm *TaskManager) FilterByPriority(p Priority) []Task {
	var result []Task
	for _, t := range tm.Tasks {
		if t.Priority == p {
			result = append(result, t)
		}
	}
	return result
}

func (tm *TaskManager) SortedByPriority() []Task {
	copy := make([]Task, len(tm.Tasks))
	for i, t := range tm.Tasks {
		copy[i] = t
	}
	priOrder := map[Priority]int{High: 0, Medium: 1, Low: 2}
	sort.Slice(copy, func(i, j int) bool {
		return priOrder[copy[i].Priority] < priOrder[copy[j].Priority]
	})
	return copy
}

func (tm *TaskManager) Stats() (total, done, pending int) {
	total = len(tm.Tasks)
	for _, t := range tm.Tasks {
		if t.Done {
			done++
		} else {
			pending++
		}
	}
	return
}

func printTask(t Task) {
	status := "⬜"
	if t.Done {
		status = "✅"
	}
	priEmoji := map[Priority]string{High: "🔴", Medium: "🟡", Low: "🟢"}
	fmt.Printf("%s [%d] %s %s\n", status, t.ID, priEmoji[t.Priority], t.Title)
}

func main() {
	fmt.Println("=== Go Task Manager ===\n")

	tm := NewTaskManager("tasks.json")

	// Demo: Tambah tasks
	t1 := tm.Add("Setup CI/CD Pipeline", High)
	t2 := tm.Add("Tulis unit tests", Medium)
	t3 := tm.Add("Update dokumentasi README", Low)
	tm.Add("Deploy ke production server", High)
	tm.Add("Review pull requests", Medium)

	// Complete salah satu
	tm.Complete(t1.ID)
	tm.Complete(t2.ID)

	_ = t3 // suppress unused

	// Tampilkan sorted
	fmt.Println("📋 Semua Task (sorted by priority):")
	for _, t := range tm.SortedByPriority() {
		printTask(t)
	}

	// Stats
	total, done, pending := tm.Stats()
	fmt.Printf("\n📊 Stats: %d total | %d selesai | %d pending\n", total, done, pending)

	// Filter high priority yang belum selesai
	fmt.Println("\n🔴 High Priority (pending):")
	for _, t := range tm.FilterByPriority(High) {
		if !t.Done {
			printTask(t)
		}
	}
}
